#!/usr/bin/env node
// gen_careers.js — Generate 250 career entries across 5 programs (50 each)
// ACC CR51-100 | MKT CR101-150 | IT CR151-200 | HOS CR201-250 | TRV CR251-300
// Usage: node scripts/gen_careers.js
const fs = require('fs');
const path = require('path');
const DATA_DIR = path.join(__dirname, '..', 'data');

// ── helpers ────────────────────────────────────────────────────────
function seededRng(seed) {
  let s = seed;
  return () => { s = (s * 16807 + 0) % 2147483647; return (s - 1) / 2147483646; };
}
function pick(arr, rng) { return arr[Math.floor(rng() * arr.length)]; }

// ── level metadata ────────────────────────────────────────────────
const LEVEL_META = {
  1: { label: 'Entry',          edu: ['ปวช./ปวส. หรือเทียบเท่า','ปวส./ปริญญาตรี หรือเทียบเท่า'] },
  2: { label: 'Professional',   edu: ['ปวส./ปริญญาตรี หรือประสบการณ์ที่เกี่ยวข้อง','ปริญญาตรี หรือประสบการณ์ที่เกี่ยวข้อง'] },
  3: { label: 'Senior/Specialist', edu: ['ปริญญาตรี หรือประสบการณ์ที่เกี่ยวข้อง','ปริญญาตรีขึ้นไปหรือประสบการณ์ที่เกี่ยวข้อง'] },
  4: { label: 'Manager',        edu: ['ปริญญาตรีขึ้นไปหรือประสบการณ์บริหารที่เกี่ยวข้อง','ปริญญาตรี/ปริญญาโท หรือประสบการณ์บริหาร'] },
  5: { label: 'Director',       edu: ['ปริญญาโทขึ้นไปหรือประสบการณ์ผู้บริหารระดับสูง','ปริญญาตรี/ปริญญาโท หรือประสบการณ์ผู้บริหาร'] },
};

// ── requirement templates by level ─────────────────────────────────
const REQ_T = {
  1: { core: { r:[3,4], w:[1.0,1.2] }, mid: { r:[2,3], w:[0.8,1.0] }, low: { r:[1,2], w:[0.6,0.8] } },
  2: { core: { r:[3,4,5], w:[1.0,1.2] }, mid: { r:[3,4], w:[1.0,1.2] }, low: { r:[2,3], w:[0.8,1.0] } },
  3: { core: { r:[4,5], w:[1.2,1.5] }, mid: { r:[3,4], w:[1.0,1.2] }, low: { r:[2,3], w:[0.8,1.0] } },
  4: { core: { r:[4,5], w:[1.2,1.5] }, mid: { r:[3,4,5], w:[1.0,1.2,1.5] }, low: { r:[2,3], w:[0.8,1.0] } },
  5: { core: { r:[4,5], w:[1.2,1.5] }, mid: { r:[4,5], w:[1.0,1.5] }, low: { r:[3,4], w:[1.0,1.2] } },
};

// ── role-type competency priorities (C01-C15 indices) ─────────────
const RC = {
  analytical:  { core:[0,3,9],  mid:[2,7,4],  low:[5,6,10,11,12,13,14] },
  creative:    { core:[4,12,14], mid:[0,5,10], low:[1,2,3,6,7,8,9,11,13] },
  people:      { core:[4,5,10], mid:[6,11,12], low:[0,1,2,3,7,8,9,13,14] },
  technical:   { core:[0,8,9],  mid:[2,3,12], low:[1,4,5,6,7,10,11,13,14] },
  operational: { core:[1,3,13], mid:[0,2,5],  low:[4,6,7,8,9,10,11,12,14] },
  strategic:   { core:[6,7,0],  mid:[1,4,5],  low:[2,3,8,9,10,11,12,13,14] },
  customer:    { core:[10,4,5], mid:[11,12,13], low:[0,1,2,3,6,7,8,9,14] },
  digital:     { core:[8,9,0],  mid:[2,3,12], low:[1,4,5,6,7,10,11,13,14] },
  leadership:  { core:[6,7,4],  mid:[0,1,5],  low:[2,3,8,9,10,11,12,13,14] },
  safety:      { core:[13,3,14], mid:[0,1,2], low:[4,5,6,7,8,9,10,11,12] },
};

function genReqs(rt, lv, rng) {
  const t = REQ_T[lv], c = RC[rt], reqs = {}, used = new Set();
  for (const [tier, idxs] of [['core',c.core],['mid',c.mid],['low',c.low]]) {
    for (const i of idxs) {
      const id = 'C'+String(i+1).padStart(2,'0');
      reqs[id] = { required: pick(t[tier].r, rng), weight: pick(t[tier].w, rng) };
      used.add(i);
    }
  }
  for (let i = 0; i < 15; i++) if (!used.has(i)) {
    reqs['C'+String(i+1).padStart(2,'0')] = { required: pick(t.mid.r, rng), weight: pick(t.mid.w, rng) };
  }
  return reqs;
}

// ── interest & workstyle profiles ─────────────────────────────────
const IP = {
  analytical:  { data:[4,5], people:[1,2], technology:[3,4], operations:[3,4], leadership:[1,2] },
  creative:    { data:[2,3], people:[3,4], technology:[3,4], operations:[2,3], leadership:[2,3] },
  people:      { data:[2,3], people:[4,5], technology:[2,3], operations:[3,4], leadership:[3,4] },
  technical:   { data:[3,4], people:[1,2], technology:[5,5], operations:[2,3], leadership:[1,2] },
  operational: { data:[3,4], people:[3,4], technology:[2,3], operations:[5,5], leadership:[2,3] },
  strategic:   { data:[4,5], people:[2,3], technology:[3,4], operations:[2,3], leadership:[4,5] },
  customer:    { data:[2,3], people:[5,5], technology:[2,3], operations:[3,4], leadership:[3,4] },
  digital:     { data:[4,5], people:[2,3], technology:[5,5], operations:[2,3], leadership:[2,3] },
  leadership:  { data:[3,4], people:[4,5], technology:[3,4], operations:[3,4], leadership:[5,5] },
  safety:      { data:[2,3], people:[3,4], technology:[2,3], operations:[4,5], leadership:[2,3] },
};
const WP = {
  analytical:  { strategic:[3,4,5], operational:[3,4], collaborative:[2,3], adaptive:[3,4] },
  creative:    { strategic:[2,3],   operational:[2,3], collaborative:[3,4], adaptive:[4,5] },
  people:      { strategic:[2,3],   operational:[3,4], collaborative:[4,5], adaptive:[3,4] },
  technical:   { strategic:[3,4],   operational:[3,4], collaborative:[2,3], adaptive:[3,4,5] },
  operational: { strategic:[2,3],   operational:[5,5], collaborative:[3,4], adaptive:[2,3] },
  strategic:   { strategic:[5,5],   operational:[2,3], collaborative:[3,4], adaptive:[3,4] },
  customer:    { strategic:[2,3],   operational:[3,4], collaborative:[4,5], adaptive:[4,5] },
  digital:     { strategic:[3,4],   operational:[2,3], collaborative:[2,3], adaptive:[4,5] },
  leadership:  { strategic:[4,5],   operational:[3,4], collaborative:[4,5], adaptive:[3,4] },
  safety:      { strategic:[3,4],   operational:[4,5], collaborative:[3,4], adaptive:[2,3] },
};
function genInterest(rt, rng) { const p=IP[rt]; return { data:pick(p.data,rng), people:pick(p.people,rng), technology:pick(p.technology,rng), operations:pick(p.operations,rng), leadership:pick(p.leadership,rng) }; }
function genWorkstyle(rt, rng) { const p=WP[rt]; return { strategic:pick(p.strategic,rng), operational:pick(p.operational,rng), collaborative:pick(p.collaborative,rng), adaptive:pick(p.adaptive,rng) }; }

// ── career data: compact [level, roleType, name_en, name_th, desc_th, desc_en, roadmap_th[], roadmap_en[]] ──
function C(lv, rt, ne, nt, dt, de, rt2, re2) { return { level:lv, roleType:rt, name_en:ne, name_th:nt, desc_th:dt, desc_en:de, roadmap_th:rt2, roadmap_en:re2 }; }

