// ═══════════════════════════════════════════════════════════════════
// GENERATION ENGINE
// ═══════════════════════════════════════════════════════════════════
const PROGRAMS = {
  ACC: { file: 'careers_acc.json', idStart: 51, clusters: ACC_CLUSTERS },
  MKT: { file: 'careers_mkt.json', idStart: 101, clusters: MKT_CLUSTERS },
  IT:  { file: 'careers_it.json',  idStart: 151, clusters: IT_CLUSTERS },
  HOS: { file: 'careers_hos.json', idStart: 201, clusters: HOS_CLUSTERS },
  TRV: { file: 'careers_trv.json', idStart: 251, clusters: TRV_CLUSTERS },
};

function generateProgram(programCode, prog) {
  const rng = seededRng(programCode.charCodeAt(0) * 1000 + programCode.charCodeAt(1) * 100);
  const careers = [];
  let id = prog.idStart;

  for (const cluster of prog.clusters) {
    for (const c of cluster.careers) {
      const lvMeta = LEVEL_META[c.level];
      careers.push({
        id: 'CR' + String(id).padStart(2, '0'),
        program: programCode,
        cluster: { id: cluster.id, th: cluster.th, en: cluster.en },
        name_en: c.name_en,
        name_th: c.name_th,
        level: c.level,
        level_label: lvMeta.label,
        description_th: c.desc_th,
        description_en: c.desc_en,
        entry_education: pick(lvMeta.edu, rng),
        requirements: genReqs(c.roleType, c.level, rng),
        interest: genInterest(c.roleType, rng),
        workstyle: genWorkstyle(c.roleType, rng),
        roadmap: c.roadmap_th,
        roadmap_en: c.roadmap_en,
      });
      id++;
    }
  }
  return careers;
}

// ── main ──────────────────────────────────────────────────────────
let total = 0;
for (const [code, prog] of Object.entries(PROGRAMS)) {
  const careers = generateProgram(code, prog);
  const outPath = path.join(DATA_DIR, prog.file);
  fs.writeFileSync(outPath, JSON.stringify(careers, null, 2), 'utf8');
  console.log(`${prog.file}: ${careers.length} careers (${careers[0].id}–${careers[careers.length-1].id})`);
  total += careers.length;
}
console.log(`\nTotal: ${total} careers generated across 5 files.`);
